const edition = globalThis.makeSubjectEdition({"year":2016,"grade":"3-4","tasksFile":"3-4_1.pdf","answersFile":"reviewed-3-4-v1.pdf","title":"XVII век. Россия накануне перемен","variant":"1","variantLabel":"Вариант 1","subject":"golden-fleece","contest":"Золотое руно","letters":"ABCD","count":60,"language":"ru","points":3,"sourceFile":"sources/golden-fleece/2016/3-4-v1.json","editionSuffix":"v1","editionLabel":"Вариант 1","sections":[{"start":1,"title":"Московская держава"},{"start":16,"title":"На просторах московского царства"},{"start":31,"title":"В избах, теремах, храмах"},{"start":41,"title":"Вертоград многоцветный"},{"start":51,"title":"Русский стиль"}],"reviewedKey":true}, [{"title":"Начало новой династии","question":"Первым царем из династии Романовых был …","choices":["Алексей Михайлович","Петр Алексеевич","Федор Алексеевич","Михаил Федорович"],"answer":3,"steps":["После Смуты Земский собор избрал шестнадцатилетнего Михаила Фёдоровича.","Его отец Филарет позднее стал патриархом."]},{"title":"Полки юного царя","question":"Так назывались военные отряды, а потом полки, созданные для юного царя Петра Алексеевича.","choices":["Потешные","Егерские","Охочие","Пластунские"],"answer":0,"steps":["Пётр обучался военному делу, разыгрывая учебные бои около Москвы.","Его потешные отряды выросли в Преображенский и Семёновский полки."]},{"title":"Род Петра по матери","question":"К этому боярскому роду Петр I принадлежал по материнской линии.","choices":["Нарышкины","Милославские","Романовы","Долгорукие"],"answer":0,"steps":["Матерью Петра была Наталья Кирилловна, вторая жена Алексея Михайловича.","Она происходила из Нарышкиных."]},{"title":"Наследник Годунова","question":"После смерти Бориса Годунова следующим русским царем стал …","choices":["Василий Шуйский","Михаил Романов","его сын Федор","Лжедмитрий I"],"answer":2,"steps":["В 1605 году престол унаследовал сын Бориса Фёдор Борисович.","Его краткое правление закончилось с приходом сторонников Лжедмитрия."]},{"title":"Учёба за границей","question":"В XVII веке первым из царей послал русских людей учиться в Европу …","choices":["Василий Шуйский","Борис Годунов","Михаил Федорович","Алексей Михайлович"],"answer":1,"steps":["Борис Годунов отправлял молодых людей учиться за границу в начале XVII века.","Среди стран, куда они поехали, были Англия и Франция."]},{"title":"Школа лекарей","question":"При этом приказе в XVII веке была создана первая в России лекарская школа.","choices":["Аптекарский","Тайных дел","Хлебный","Великороссийский"],"answer":0,"steps":["Аптекарский приказ ведал лекарствами и работой лекарей.","В 1654 году при нём открылась школа подготовки отечественных специалистов."]},{"title":"Командир ополчения","question":"Этот военачальник командовал народным ополчением при освобождении Москвы от поляков в 1612 году.","choices":["Д. Пожарский","М. Кутузов","Д. Донской","А. Невский"],"answer":0,"steps":["Кузьма Минин помог собрать средства и людей в Нижнем Новгороде.","Военное руководство ополчением, освободившим Москву, поручили Дмитрию Пожарскому."]},{"title":"Восстание на Волге","question":"Руководителем народного восстания 1670-1671 годов, крупнейшего в XVII веке, был …","choices":["Е. Пугачев","Лжедмитрий I","С. Разин","К. Минин"],"answer":2,"steps":["Степан Разин пришёл с Дона на Волгу, где к казакам присоединялись жители городов и крестьяне.","Восставшие взяли Астрахань, но потерпели поражение под Симбирском."]},{"title":"Кто взял Азов","question":"В 1637 году турецкую крепость Азов взяли …","choices":["янычары","казаки","стрельцы","драгуны"],"answer":1,"steps":["Крепостью Азов управляла Османская империя, и она контролировала выход из Дона к морю.","В 1637 году её взяли донские казаки."]},{"title":"Служба по отечеству","question":"Государевыми служилыми людьми «по отечеству» были …","choices":["гости","пушкари","дворяне","казаки"],"answer":2,"steps":["Служба «по отечеству» была наследственной и зависела от происхождения.","К этому разряду принадлежали дворяне, получавшие землю за службу."]},{"title":"Царь в десять лет","question":"Этот царь, в будущем получивший прозвище «Великий», был коронован в 10 лет.","choices":["Алексей Михайлович","Михаил Федорович","Петр Алексеевич","Федор Алексеевич"],"answer":2,"steps":["Пётр Алексеевич венчался на царство вместе со старшим братом Иваном в 1682 году.","На тот момент Петру было десять лет."]},{"title":"Кардисский мир","question":"Кардисский мир 1661 года завершил войну России и …","choices":["Турции","Речи Посполитой","Китая","Швеции"],"answer":3,"steps":["Договор заключили в Кардисе после русско-шведской войны.","Стороны восстановили довоенную границу."]},{"title":"Столбовский мир","question":"По Столбовскому миру 1617 года, Швеция вернула России город …","choices":["Ивангород","Орешек","Новгород","Корелу"],"answer":2,"steps":["Швеция вернула по договору Новгород и ряд других городов.","Земли у выхода к Балтийскому морю остались за Швецией."]},{"title":"Условия «Вечного мира»","question":"Благодаря условиям «Вечного мира» 1686 года с Речью Посполитой Россия впервые в истории …","choices":["получила границу с Германской империей","добилась признания царского титула правителей","получила выход к Черному морю","вступила в европейскую коалицию"],"answer":3,"steps":["Мир с Речью Посполитой в 1686 году закрепил принадлежность Киева России.","Россия одновременно вошла в союз европейских государств, направленный против Османской империи."]},{"title":"Полки нового строя","question":"В полках «нового строя» служили …","choices":["солдаты","рынды","рекруты","холопы"],"answer":0,"steps":["Такие полки формировались и обучались по европейскому образцу.","Пехотинцев в них называли солдатами."]},{"title":"Между Азией и Америкой","question":"Пролив между Азией и Америкой открыл русский путешественник …","choices":["С. Дежнев","И. Москвитин","В. Беринг","В. Поярков"],"answer":0,"steps":["В 1648 году Семён Дежнёв с товарищами прошёл морем вокруг крайней северо-восточной части Азии.","Так они оказались в проливе между Азией и Америкой задолго до экспедиции Беринга."]},{"title":"Дома москвичей","question":"Дома простых москвичей в XVII веке обычно строились из …","choices":["кирпича","бетона","дерева","камня"],"answer":2,"steps":["Обычные жилища возводили из брёвен и покрывали деревянной кровлей.","Из-за плотной деревянной застройки московские пожары быстро распространялись."]},{"title":"Территория вокруг города","question":"Основная единица территориального деления России в XVII веке – это …","choices":["княжество","уезд","губерния","область"],"answer":1,"steps":["Уезд охватывал город и подчинённые ему земли.","Из города уездом управлял воевода."]},{"title":"Торговая часть города","question":"Часть города, в которой жили торговцы и ремесленники, называлась в XVII веке …","choices":["детинцем","посадом","палисадом","острогом"],"answer":1,"steps":["Посад складывался рядом с городским укреплением.","В нём располагались торговые ряды и дворы ремесленников."]},{"title":"Торговля между краями","question":"Важнейшими центрами торговли между разными регионами страны в XVII веке были …","choices":["ярмарки","торговые ряды","рынки","базары"],"answer":0,"steps":["На большие ярмарки приезжали купцы из разных мест, привозя товары для обмена и продажи.","Одной из крупнейших была Макарьевская ярмарка на Волге."]},{"title":"Кем был Сусанин","question":"Национальный герой России Иван Сусанин был …","choices":["крестьянином","стрельцом","посадским человеком","казаком"],"answer":0,"steps":["Иван Сусанин был крестьянином из костромских земель.","По преданию, ему было известно укрытие Михаила Романова, но он не выдал его."]},{"title":"Корабль Алексея","question":"Первый русский корабль, построенный при Алексее Михайловиче по европейскому образцу, назывался …","choices":["«Сокол»","«Орел»","«Беркут»","«Сапсан»"],"answer":1,"steps":["«Орёл» построили в селе Дединове на Оке.","Его предназначали для охраны торговых судов на Каспии."]},{"title":"Группы купцов","question":"Богатые купцы в Московском государстве XVII века делились на …","choices":["сотни","цехи","полки","гильдии"],"answer":0,"steps":["Купцов объединяли по разрядам, от которых зависели их обязанности.","В XVII веке существовали, в частности, гостиная и суконная сотни."]},{"title":"Товар для Европы","question":"Наибольшую прибыль Россия в XVII веке получала от продажи в Европу …","choices":["серебра","меди","мехов","золота"],"answer":2,"steps":["Соболий и другой ценный мех поступал в Москву главным образом из Сибири.","Его дорого продавали европейским купцам."]},{"title":"Владельцы крестьян","question":"В России XVII века наряду с государем, боярами и дворянами крепостными крестьянами владели …","choices":["служилые люди «по прибору»","казаки","купцы","монастыри"],"answer":3,"steps":["Монастыри получали земли вместе с жившими на них крестьянами.","Крупные обители управляли хозяйствами и собирали оброк подобно светским владельцам."]},{"title":"Резиденция в Москве","question":"Московская резиденция русских царей в XVII веке располагалась в …","choices":["Донском монастыре","Белом городе","Китай-городе","Кремле"],"answer":3,"steps":["Палаты государя и главные государственные учреждения располагались за кремлёвскими стенами.","В XVII веке в Кремле построили Теремной дворец."]},{"title":"Морская торговля","question":"Крупнейшим центром торговли России с европейскими странами в XVII веке был город …","choices":["Архангельск","Нижний Новгород","Астрахань","Тихвин"],"answer":0,"steps":["Архангельск лежит у Северной Двины и связан с Белым морем.","Через его порт в страну приходили корабли из Западной Европы."]},{"title":"Дань Сибири","question":"Дань, которую платили народы Сибири в русскую казну, называлась …","choices":["выход","пошлина","поминки","ясак"],"answer":3,"steps":["Ясаком называли дань, поступавшую в казну от местных народов.","В Сибири её часто собирали пушниной."]},{"title":"Первые уроки Петра","question":"Юный царь Петр получил первые уроки судовождения на реке …","choices":["Оке","Неглинной","Яузе","Москве"],"answer":2,"steps":["В усадьбе Измайлово нашли старый английский ботик.","Пётр учился управлять им под парусом на Яузе."]},{"title":"Район для иностранцев","question":"Во второй половине XVII века выходцы из Западной Европы должны были жить в Москве в …","choices":["Немецкой слободе","Мещанской слободе","Китай-городе","разных частях города"],"answer":0,"steps":["В XVII веке западноевропейских жителей Москвы переселяли в особую слободу у Яузы.","Слово «немецкая» в её названии тогда относилось к разным иностранцам."]},{"title":"Воротник кафтана","question":"Высокий воротник, который в XVII веке стали крепить к кафтану, назывался …","choices":["ферязь","козырь","охабень","терлик"],"answer":1,"steps":["Высокий стоячий воротник называли козырем.","Он выступал над краем кафтана и мог быть богато украшен."]},{"title":"Старинный портрет","question":"Произведения русской портретной живописи в XVII веке назывались …","choices":["парсунами","изографами","ликами","образами"],"answer":0,"steps":["Слово «парсуна» произошло от «персона».","Такие портреты отдельных людей сохраняли приёмы, которыми пользовались иконописцы."],"figure":{"src":"assets/golden-fleece/2016/lessons/3-4-v1/32.webp","alt":"Портрет мужчины на золотистом фоне","width":120,"height":160}},{"title":"Мастера Палеха","question":"В XVII веке мастера из села Палех прославились …","choices":["стенными росписями","иконами","лаковыми шкатулками","ювелирными изделиями"],"answer":1,"steps":["В XVII веке в Палехе работали мастера иконописи.","Лаковая миниатюра, за которую село сегодня известно, выросла позднее из навыков палехских художников."]},{"title":"Блеск хохломы","question":"В хохломском промысле для росписи посуды в XVII веке применялся порошок из этого металла.","choices":["Олово","Серебро","Золото","Алюминий"],"answer":0,"steps":["Деревянную поверхность покрывали порошком олова, а затем лаком.","После обработки возникал золотистый цвет без слоя золота."],"figure":{"src":"assets/golden-fleece/2016/lessons/3-4-v1/34.webp","alt":"Деревянная посуда с растительным орнаментом","width":120,"height":127}},{"title":"Окна зимой","question":"Автор исторических записок о России Павел Алеппский утверждал, что в Москве XVII века зимой в окна вставляли …","choices":["шелковую ткань","хрусталь","куски льда","цветное стекло"],"answer":2,"steps":["Павел Алеппский записывал наблюдения во время поездки в Московское государство.","Среди необычных способов заполнить проём он упомянул прозрачный лёд."]},{"title":"Кремль митрополита","question":"Кремль в этом городе был возведен в XVII веке по приказу местного митрополита.","choices":["Вологда","Коломна","Астрахань","Ростов Великий"],"answer":3,"steps":["Митрополит Иона Сысоевич устроил в Ростове резиденцию с храмами и стенами.","Позднее весь ансамбль стали называть Ростовским кремлём."],"figure":{"src":"assets/golden-fleece/2016/lessons/3-4-v1/36.webp","alt":"Белокаменные стены и башни с куполами","width":172,"height":115}},{"title":"Откуда возили глину","question":"Из этой местности, известной своим гончарным промыслом с XIV века, по указу Алексея Михайловича доставлялась глина для нужд Аптекарского приказа.","choices":["Дымково","Каргополь","Гжель","Хохлома"],"answer":2,"steps":["Гжельские гончары использовали местную глину для посуды.","Её качество сделало промысел известным, а часть сырья брали для аптечных сосудов."]},{"title":"Транспорт архиереев","question":"По словам немецкого ученого Адама Олеария, этим транспортом пользовались московские архиереи в самых торжественных случаях.","choices":["Сани","Паланкин","Струг","Карета"],"answer":0,"steps":["Олеарий описывал сани как почётный выезд, которым пользовались архиереи.","Такой вид транспорта мог служить знаком торжественности."]},{"title":"Первая школа театра","question":"Первая театральная школа России была основана при …","choices":["церкви Немецкой слободы","Иноземном приказе","Оружейной палате","Славяно-греко-латинской академии"],"answer":0,"steps":["Пастор Иоганн Грегори собрал и обучал актёров для нового придворного театра.","Подготовка началась при церкви в Немецкой слободе."]},{"title":"Каменный дворец","question":"Основанием этого каменного здания стали постройки XVI века.","choices":["Дворец в Коломенском","Теремной дворец","Измайловский дворец","Потешный дворец"],"answer":1,"steps":["Теремной дворец возвели над более ранними постройками великокняжеского двора.","Нижние части прежних палат послужили основанием нового здания."],"figure":{"src":"assets/golden-fleece/2016/lessons/3-4-v1/40.webp","alt":"Дворцовый фасад с резными наличниками","width":120,"height":124}},{"title":"Книга для чтения","question":"Эту книгу Карион Истомин написал для обучения детей.","choices":["Арифметика","Букварь","Сборник сказок","Псалтырь"],"answer":1,"steps":["В букваре Кариона Истомина каждой букве соответствуют рисунки и стихи.","Иллюстрации связывают звучание и написание буквы с знакомыми предметами."]},{"title":"Судья и свёрток","question":"Судья из повести «Суд Шемякин» обрадовался тому, что …","choices":["наказал богатых","вынес справедливый приговор","получил награду от бедняка","не был ушиблен камнем"],"answer":3,"steps":["Шемяка решил, что бедняк показывает ему обещанный подарок.","Когда выяснилось, что в свёртке был камень, судья обрадовался, что остался цел."]},{"title":"Время работы и отдыха","question":"Это выражение, ставшее крылатым, записано в сборнике правил соколиной охоты, составленном царем Алексеем Михайловичем.","choices":["«Делу время и потехе час»","«Век живи – век учись»","«Талант трудом добывают»","«Смелость города берет»"],"answer":0,"steps":["Алексей Михайлович любил соколиную охоту и изложил её правила в особой книге.","В ней встретилось выражение, которое теперь употребляют и вне охотничьего быта."]},{"title":"Первый театр при дворе","question":"Первый придворный театр появился в России при этом монархе.","choices":["Федор Алексеевич","Петр Алексеевич","Василий Иоаннович","Алексей Михайлович"],"answer":3,"steps":["В 1672 году в резиденции Алексея Михайловича сыграли пьесу на библейский сюжет об Эсфири.","Её поставил пастор Грегори."]},{"title":"Герой старой азбуки","question":"Герою «Азбуки о голом и небогатом человеке» не поехать в гости, потому что …","choices":["псы на двор не пускают","не зовут","не пускает жена Соломонида","не благословляет поп Фома"],"answer":1,"steps":["Бедняк в сатирическом произведении перечисляет свои злоключения по буквам азбуки.","В гости он не едет, потому что его туда не зовут."]},{"title":"Участник рыбьего суда","question":"Окунь из «Повести о Ерше Ершовиче сыне Щетинникове» был …","choices":["понятым","судьей","воеводой","приставом"],"answer":3,"steps":["Повесть переносит правила старого суда в мир рыб.","Окунь исполняет обязанности пристава, направленного по делу Ерша."]},{"title":"Необычное приданое","question":"В этом произведении рассказывается о хозяйстве, в котором хранятся сорок кадушек соленых лягушек и водятся дойные кошки.","choices":["«Роспись о приданом»","«Сказание о роскошном житии и веселии»","«Лечебник на иноземцев»","«Азбука о голом и небогатом человеке»"],"answer":0,"steps":["«Роспись о приданом» подражает хозяйственному перечню.","Солёные лягушки и дойные кошки превращают такой список в пародию."]},{"title":"Куда шёл горожанин","question":"В повести «Суд Шемякин» горожанин, пострадавший от бедного крестьянина, направлялся …","choices":["в баню","в трактир","на базар","в церковь"],"answer":0,"steps":["Один из эпизодов повести связан с человеком, которого сын вёз в баню.","Тот погиб под бедняком, прыгнувшим с моста."]},{"title":"Пародийное лекарство","question":"В этом произведении «курячий высокий глас» смешивается с «крупным кошачьим ворчаньем».","choices":["«Роспись о приданом»","«Сказание о роскошном житии и веселии»","«Лечебник на иноземцев»","«Повесть о Куре и Лисице»"],"answer":2,"steps":["«Лечебник на иноземцев» пародирует советы о приготовлении лекарств.","Рецепты смешивают предметы и звуки, которые невозможно соединить."]},{"title":"Голова богатыря","question":"Голова богатыря, с которой разговаривал главный герой «Повести о Еруслане Лазаревиче», принадлежала …","choices":["брату царевны Настасьи","сыну Прохора-царя","царю Далмату","князю Ивану"],"answer":1,"steps":["Еруслан встречает говорящую голову, оставшуюся после битвы со змеем.","Она принадлежала сыну царя Прохора и указывает на меч, которым можно одолеть противника."]},{"title":"Казаки на картине","question":"Эту историческую картину И. Репин посвятил вольному казачеству.","choices":["«Заседание Государственного совета»","«Запорожцы пишут письмо турецкому султану»","«Бурлаки на Волге»","«Возвращение с войны»"],"answer":1,"steps":["У Репина казаки столпились вокруг пишущего человека и смеются над придумываемым ответом.","Адресат письма в названии картины — турецкий султан."],"figure":{"src":"assets/golden-fleece/2016/lessons/3-4-v1/51.webp","alt":"Картина с казаками за столом","width":560,"height":331,"detailSrc":"assets/golden-fleece/2016/lessons/3-4-v1/51-detail.webp"}},{"title":"Опера по Пушкину","question":"Этот композитор написал оперу «Борис Годунов» по сюжету трагедии А. Пушкина.","choices":["М. Мусоргский","П. Чайковский","М. Глинка","Н. Римский-Корсаков"],"answer":0,"steps":["Пушкин написал трагедию о борьбе за престол в начале Смуты.","Мусоргский превратил её в оперу и добавил собственные сцены."]},{"title":"Памятник двум героям","question":"В этом городе установлен памятник русским национальным героям К. Минину и Д. Пожарскому, созданный И. Мартосом.","choices":["Великий Новгород","Ярославль","Таганрог","Москва"],"answer":3,"steps":["Скульптуру Ивана Мартоса установили в 1818 году на Красной площади в Москве.","Минин в композиции обращается к сидящему Пожарскому."],"figure":{"src":"assets/golden-fleece/2016/lessons/3-4-v1/53.webp","alt":"Бронзовый памятник с двумя фигурами","width":118,"height":159}},{"title":"Первая опера Чайковского","question":"Как называется первая опера П. Чайковского, действие которой происходит в XVII веке?","choices":["«Воевода»","«Опричник»","«Сон на Волге»","«Чародейка»"],"answer":0,"steps":["«Воевода» написан по пьесе Островского.","На её сценическую историю приходится первое исполнение оперы Чайковского в Большом театре."]},{"title":"Деревянный ансамбль","question":"Этот музей-заповедник, демонстрирующий развитие традиций русского деревянного зодчества XVII века, объявлен памятником ЮНЕСКО.","choices":["«Кижи»","«Костромская слобода»","«Малые Корелы»","«Витославлицы»"],"answer":0,"steps":["На острове Кижи сохранились деревянные церкви и колокольня.","Кижский погост включён в список всемирного наследия ЮНЕСКО."],"figure":{"src":"assets/golden-fleece/2016/lessons/3-4-v1/55.webp","alt":"Ансамбль деревянных церквей у воды","width":168,"height":128}},{"title":"Костюмы при дворе","question":"В 1903 году придворные Николая II и императорская семья оделись в парадные костюмы времен царя Алексея Михайловича по случаю празднования …","choices":["300-летия Дома Романовых","рождения царевича Алексея","коронации Николая II","290-летия Дома Романовых"],"answer":3,"steps":["На балу 1903 года гости носили наряды, воспроизводившие моду московского двора XVII века.","Наименование юбилея следует понимать как отсчёт от восшествия Романовых в 1613 году."]},{"title":"Защита монастыря","question":"В этой картине отобразил героическую оборону Троице-Сергиева монастыря в 1608 году русский художник …","choices":["В. Суриков","К. Маковский","В. Верещагин","Н. Рерих"],"answer":2,"steps":["Василий Верещагин написал многофигурную сцену защиты Троице-Сергиевой обители.","Художник расположил защитников на стенах и у ворот монастыря."],"figure":{"src":"assets/golden-fleece/2016/lessons/3-4-v1/57.webp","alt":"Сцена осады монастыря","width":560,"height":346,"detailSrc":"assets/golden-fleece/2016/lessons/3-4-v1/57-detail.webp"}},{"title":"Стих для сказки","question":"Этим популярным в народной литературе XVII века стихом написана «Сказка о попе и о работнике его Балде» А. Пушкина.","choices":["Былина","Песня","Раек","Частушка"],"answer":2,"steps":["Раёшный стих держится рифмой, а число слогов в строках может различаться.","Такой ритм напоминает речь ярмарочного рассказчика и подходит сказке о Балде."]},{"title":"Живопись о боярах","question":"Автор этой картины прославился изображениями боярского быта XVII века.","choices":["В. Верещагин","А. Васнецов","В. Суриков","К. Маковский"],"answer":3,"steps":["Константин Маковский собирал старинные вещи, ткани и украшения.","Их можно увидеть в его праздничных сценах из жизни бояр."],"figure":{"src":"assets/golden-fleece/2016/lessons/3-4-v1/59.webp","alt":"Женщина в нарядном старинном костюме","width":118,"height":160}},{"title":"От теремов к дворцу","question":"В фасадах этого московского здания XIX века были использованы мотивы декора Теремного дворца.","choices":["Дворец Волковых-Юсуповых","Большой Кремлевский дворец","Храм Христа Спасителя","Третьяковская галерея"],"answer":1,"steps":["Большой Кремлёвский дворец возводили в XIX веке рядом со старинными палатами.","Его архитектор использовал детали, напоминающие убранство Теремного дворца."],"figure":{"src":"assets/golden-fleece/2016/lessons/3-4-v1/60.webp","alt":"Длинный фасад дворца на холме","width":177,"height":103}}]);
edition.sources.readers = {"tasksUrl":"assets/golden-fleece/2016/3-4_1-reading.pdf"};
